import { RayBody, RayLight, TiledBoolProp } from "type";
import { calculateAngle, formatProperties } from "utils";

import { GameScene } from "../GameScene";
import { moveShadow } from "./utils";
import { Light } from "../Light";

const debug = true;

const rayConfig = {
  shadowColor: 0x000000,
  shadowAlpha: 0.25,
};

export class Raycaster {
  constructor(
    scene: GameScene,
    // light: RayLight, bodies: RayBody[]
  ) {
    // scene.objectState.flames

    const shadows = scene.objectState.shadows.objects.map(
      ({ x = 0, y = 0, height = 0, width = 0, properties }) => {
        const props = formatProperties<"rectangle">(properties);
        const rectangle = props.rectangle as TiledBoolProp;

        if (!rectangle.value) {
          const shadow = scene.add.circle(
            x + width / 2,
            y + height / 2,
            width / 2,
            rayConfig.shadowColor,
            rayConfig.shadowAlpha,
          );
          shadow.setScale(width / shadow.width, height / shadow.height);
          return shadow;
        } else {
          const shadow = scene.add.rectangle(
            x + width / 2,
            y + height / 2,
            width,
            height,
            rayConfig.shadowColor,
            rayConfig.shadowAlpha,
          );
          return shadow;
        }
      },
    );

    const reducedShadows = shadows.reduce(
      (acm, shadow) => {
        const { x = 0, y = 0 } = shadow;
        const currentLight = scene.lightElements.static?.list.find((light) => {
          const {
            light: { x: lx, y: ly, radius },
          } = light;
          const leftTop = { x: lx - radius, y: ly - radius };
          const rightBottom = { x: lx + radius, y: ly + radius };

          // чи тінь входить до цього джерела світла ?
          return (
            x >= leftTop.x &&
            y >= leftTop.y &&
            x <= rightBottom.x &&
            y <= rightBottom.y
          );
        });

        if (currentLight) {
          //Перевірити чи це джерело світла уже було збережено
          const currentSource = acm.find(
            (current) => current.light === currentLight,
          );

          if (currentSource) {
            currentSource.shadows.push(shadow);
          } else {
            acm.push({
              light: currentLight,
              shadows: [shadow],
            });
          }
        } else {
          const currentSource = acm.find(
            (current) => current.light === currentLight,
          );
        }

        return acm;
      },
      [] as {
        light: Light | null;
        shadows: (Phaser.GameObjects.Arc | Phaser.GameObjects.Rectangle)[];
      }[],
    );

    console.log("shadows", reducedShadows);

    if (debug) {
      reducedShadows.forEach(({ light: { light }, shadows }) => {
        const lightEdge = scene.add
          .circle(light.x, light.y, light.radius, 0xff0000)
          .setDepth(Infinity)
          .setAlpha(0.075);
        const lines = shadows.map(({ height, width, x, y }) => {
          const line = new Phaser.Geom.Line(light.x, light.y, x, y);
          const graphics = scene.add
            .graphics({
              lineStyle: { width: 1, color: 0x00ff00 },
            })
            .setDepth(Infinity);

          graphics.strokeLineShape(line);
          return line;
        });
        const defaultPositions = shadows.map(
          ({ height, width, x, y, type }) => {
            scene.add
              .rectangle(x, y, width, height, 0xffff00, 0.1)
              .setDepth(Infinity);
          },
        );
      });
    }
    // shadows.forEach((shadow) => {
    //   const { height, width, x, y } = shadow;
    //   const angle = calculateAngle(light.x, light.y, x, y);
    //   const { x: moveX, y: moveY } = moveShadow(angle);
    //   // console.log("🚀 ~ ", angle, moveX, moveY);
    //   shadow.setPosition(x + width * 0.15 * moveX, y + height * 0.15 * moveY);
    // });
  }
}
